    for level in range(17):
        if parent(a, level) == parent(b, level):
            return level
    return 16


def distance_cells(a, b):
    ax, ay = cell_xy(a)
    bx, by = cell_xy(b)
    return max(abs(ax - bx), abs(ay - by))

